-- Runner copy of server/src/db-draft/0004_canonical_districts_and_tenants.sql.
-- Generated by scripts/build-tenant-migration.mjs; edit the draft and regenerate, do not hand-edit
-- both. Differences from the draft: psql meta-commands removed, and BEGIN/COMMIT removed because
-- the migration runner applies every file inside its own transaction (and records the result in
-- schema_migrations). Semantics are otherwise identical.

-- =============================================================================
-- DHAROHAR — DRAFT migration 0004: canonical district registry + tenant
--            relationships (phases 1-3 of docs/DISTRICT-TENANCY-MODEL.md)
--
-- NOT WIRED INTO THE RUNNER. It lives in server/src/db-draft until the disposable-copy
-- test sequence in that document's §7 has been executed and read. A migration that
-- changes who can see what is not a change to make by accident.
--
-- WHAT IT IMPLEMENTS (the owner's architectural decision, 2026-10-19)
--   * Districts become canonical geography with a stable identifier. The identifier is
--     created here, alongside the existing key, so the running application is never left
--     without a working one. Removing "a district name is globally unique" and repointing
--     the foreign keys are deliberately in 0005, not here.
--   * Organization<->district becomes an explicit many-to-many relationship with a kind
--     (administers / audits / reads), a granter and a required reason. Several
--     organizations may relate to the same district.
--   * organization_units holds an organization's internal units. They are not districts,
--     and a unit code is unique only inside the organization that issued it.
--   * Exactly one tenant is created: ORG-DHAROHAR-DEMO, named as a demo. Every mapping
--     below is a mapping into that tenant and asserts nothing about real administration.
--
-- WHAT IT REFUSES
--   * Registry rows created by the test suites (code LIKE 'probe %') are marked
--     kind='test_fixture' and receive NO organization relationship. Their parcels keep
--     their district reference — history preserved — but they stay unreachable to every
--     officer until a person decides what they are.
--   * state_code stays NULL. Nothing is inferred.
--   * A child row whose district_code matches no registry row aborts the file and lists
--     the codes. It will not guess which district a record belongs to.
--   * It deletes nothing and changes no land-record fact.
-- =============================================================================



-- ─────────────────────────────────────────────────────────────────────────────
-- PHASE 1 — new objects. Additive only; nothing dropped, nothing repointed.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE EXTENSION IF NOT EXISTS pgcrypto;

ALTER TABLE districts ADD COLUMN IF NOT EXISTS id             UUID;
ALTER TABLE districts ADD COLUMN IF NOT EXISTS kind           TEXT NOT NULL DEFAULT 'canonical'
  CHECK (kind IN ('canonical','test_fixture','retired'));
ALTER TABLE districts ADD COLUMN IF NOT EXISTS state_code     TEXT;
ALTER TABLE districts ADD COLUMN IF NOT EXISTS country_code   TEXT NOT NULL DEFAULT 'IN';
ALTER TABLE districts ADD COLUMN IF NOT EXISTS canonical_name TEXT;
ALTER TABLE districts ADD COLUMN IF NOT EXISTS name_key       TEXT;
ALTER TABLE districts ADD COLUMN IF NOT EXISTS retired_at     TIMESTAMPTZ;
ALTER TABLE districts ADD COLUMN IF NOT EXISTS notes          TEXT;

UPDATE districts SET id = gen_random_uuid() WHERE id IS NULL;
-- A column cannot be referenced by a foreign key until it is unique. 0005 promotes id to the
-- primary key; until then an explicit UNIQUE is what makes "children reference the identifier"
-- legal SQL rather than an intention. Without this line the very first dependent table fails
-- with "there is no unique constraint matching given keys" — which is how the harness caught it.
--
-- Added only when missing, never dropped and re-added: organization_districts references this
-- key, so `DROP CONSTRAINT` fails with "other objects depend on it" and re-running the file on an
-- already-migrated database breaks idempotence for no good reason.
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'ux_districts_id' AND conrelid = 'districts'::regclass) THEN
    ALTER TABLE districts ADD CONSTRAINT ux_districts_id UNIQUE (id);
  END IF;
END
$do$;
-- canonical_name begins as the display name already stored, and name_key is its match form.
-- Both are derived from the row that exists; neither is a new claim about geography.
UPDATE districts SET canonical_name = name WHERE canonical_name IS NULL;
UPDATE districts SET name_key = lower(btrim(canonical_name)) WHERE name_key IS NULL;

CREATE TABLE IF NOT EXISTS organization_districts (
    organization_id  TEXT        NOT NULL REFERENCES organizations(id),
    district_id      UUID        NOT NULL REFERENCES districts(id),
    relationship     TEXT        NOT NULL
                     CHECK (relationship IN ('administers','audits','reads')),
    granted_by       TEXT        NOT NULL,
    reason           TEXT        NOT NULL CHECK (length(btrim(reason)) >= 5),
    granted_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at       TIMESTAMPTZ,
    PRIMARY KEY (organization_id, district_id, relationship)
);
CREATE INDEX IF NOT EXISTS idx_org_districts_district
  ON organization_districts (district_id) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_org_districts_org
  ON organization_districts (organization_id) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS organization_units (
    id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  TEXT        NOT NULL REFERENCES organizations(id),
    parent_unit_id   UUID        NULL REFERENCES organization_units(id),
    district_id      UUID        NULL REFERENCES districts(id),
    kind             TEXT        NOT NULL,
    name             TEXT        NOT NULL,
    unit_code        TEXT,
    is_active        BOOLEAN     NOT NULL DEFAULT true,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ux_org_unit_code UNIQUE (organization_id, unit_code)
);
CREATE INDEX IF NOT EXISTS idx_org_units_org
  ON organization_units (organization_id) WHERE is_active;

-- ─────────────────────────────────────────────────────────────────────────────
-- PHASE 2 — the demo tenant, and only the mappings that are unambiguous.
-- ─────────────────────────────────────────────────────────────────────────────

DO $do$
DECLARE
  demo_org   constant text := 'ORG-DHAROHAR-DEMO';
  demo_name  constant text := 'Dharohar Demo Organization';
  existing   text;
  n          integer;
  codes      text;
BEGIN
  SELECT name INTO existing FROM organizations WHERE id = demo_org;

  IF existing IS NOT NULL AND existing <> demo_name THEN
    RAISE EXCEPTION E'[DEMO_TENANT_IDENTITY_CONFLICT] organization % already exists named ''%'', not ''%''.\n  The demo tenant''s identity is a fact, not a preference. Rename it through an explicit action or choose a different id. Nothing was changed.',
      demo_org, existing, demo_name;
  ELSIF existing IS NULL THEN
    -- No audit row: this runs inside a migration, where there is no acting officer to attribute
    -- it to, and inventing one would put a fictional person into the audit chain.
    INSERT INTO organizations (id, name, description)
    VALUES (demo_org, demo_name,
      'Synthetic tenant created by draft migration 0004 for demonstration data only. Its existence and every association it holds are evidence about nothing real. See docs/DISTRICT-TENANCY-MODEL.md decision D5.');
    RAISE NOTICE '[0004] created demo tenant % (%)', demo_org, demo_name;
  ELSE
    RAISE NOTICE '[0004] demo tenant % already present with the expected name', demo_org;
  END IF;

  -- Classify suite-created rows first, so the report shows them as a decision taken rather
  -- than as rows that quietly got left out.
  UPDATE districts
     SET kind = 'test_fixture',
         notes = btrim(coalesce(notes, '') || ' [0004] classified as test-suite fixture by name pattern; not canonical geography')
   WHERE code LIKE 'probe %' AND kind <> 'test_fixture';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    RAISE NOTICE '[0004] classified % registry row(s) as test_fixture; mapped NONE of them to any organization', n;
  END IF;

  INSERT INTO organization_districts
    (organization_id, district_id, relationship, granted_by, reason)
  SELECT 'ORG-DHAROHAR-DEMO', d.id, 'administers', 'migration:0004',
         'Baseline association for demonstration data: this district exists in a database holding only synthetic records. Not a statement about real administration.'
    FROM districts d
   WHERE d.kind = 'canonical'
   ORDER BY d.code
  ON CONFLICT (organization_id, district_id, relationship) DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RAISE NOTICE '[0004] canonical districts associated with the demo tenant: %', n;

  SELECT string_agg(code, ', ' ORDER BY code) INTO codes FROM districts WHERE kind = 'test_fixture';
  IF codes IS NOT NULL THEN
    RAISE NOTICE '[0004] UNMAPPED, awaiting a governance decision: %', left(codes, 500);
  END IF;
END
$do$;

-- ─────────────────────────────────────────────────────────────────────────────
-- PHASE 3 — children gain the identifier reference, by exact match only.
-- ─────────────────────────────────────────────────────────────────────────────

ALTER TABLE parcels             ADD COLUMN IF NOT EXISTS district_id UUID REFERENCES districts(id);
ALTER TABLE land_documents      ADD COLUMN IF NOT EXISTS district_id UUID REFERENCES districts(id);
ALTER TABLE users               ADD COLUMN IF NOT EXISTS district_id UUID REFERENCES districts(id);
ALTER TABLE user_jurisdictions  ADD COLUMN IF NOT EXISTS district_id UUID REFERENCES districts(id);

DO $do$
DECLARE
  t          text;
  dupes      text;
  orphaned   text;
  unmapped   integer;
  mapped     integer;
BEGIN
  -- Checked once, not per table: the file is about to rely on code -> id being one answer.
  -- Today code is the primary key, so this cannot fire. It stays because 0005 removes that
  -- guarantee, and a guard invented after the fact has never been observed failing.
  SELECT string_agg(code, ', ' ORDER BY code) INTO dupes
    FROM (SELECT code FROM districts GROUP BY code HAVING count(*) > 1) d;
  IF dupes IS NOT NULL THEN
    RAISE EXCEPTION E'[DISTRICT_CODE_AMBIGUOUS] % code(s) resolve to more than one registry row: %\n  Which row is canonical is a decision, not a min(). Nothing was changed.',
      (SELECT count(*) FROM (SELECT code FROM districts GROUP BY code HAVING count(*) > 1) x), dupes;
  END IF;

  FOREACH t IN ARRAY ARRAY['parcels','land_documents','users','user_jurisdictions'] LOOP
    EXECUTE format(
      'UPDATE %I c SET district_id = d.id
         FROM districts d
        WHERE c.district_code IS NOT NULL
          AND c.district_id IS NULL
          AND d.code = c.district_code', t);
    GET DIAGNOSTICS mapped = ROW_COUNT;

    EXECUTE format(
      'SELECT count(*) FROM %I WHERE district_code IS NOT NULL AND district_id IS NULL', t) INTO unmapped;

    IF unmapped > 0 THEN
      EXECUTE format(
        'SELECT string_agg(dc, %L ORDER BY dc) FROM (
           SELECT DISTINCT district_code AS dc FROM %I
            WHERE district_code IS NOT NULL AND district_id IS NULL LIMIT 25
         ) s', ', ', t) INTO orphaned;

      RAISE EXCEPTION E'[DISTRICT_UNRESOLVED] % row(s) in table % carry a district_code with no registry row. Codes: %\n  HINT: register the district deliberately (POST /api/admin/districts) or correct the records through an audited action, then re-run. This migration will not guess which district a land record belongs to. Nothing was changed.',
        unmapped, t, coalesce(orphaned, '(list unavailable)');
    END IF;

    RAISE NOTICE '[0004] %.district_id backfilled: % row(s)', t, mapped;
  END LOOP;
END
$do$;

-- The three district representations must agree once an id exists.
--
-- A CHECK cannot contain a subquery in PostgreSQL — "cannot use subquery in check constraint" — so
-- the rule id -> code == district_code is NOT enforced by a constraint here, and pretending
-- otherwise would have meant a migration that simply fails to run. It is enforced by the report
-- below (which aborts on drift), and when phase 5 makes the application write district_id the rule
-- moves into the existing dharohar_sync_district_code trigger, beside the text/code CHECK that
-- migration 0003 already maintains. That ordering is deliberate: a write path that does not exist
-- yet does not need a constraint today, but it does need one before it ships.
DO $do$
DECLARE
  drift integer;
  t     text;
BEGIN
  FOREACH t IN ARRAY ARRAY['parcels','land_documents','users','user_jurisdictions'] LOOP
    EXECUTE format(
      'SELECT count(*) FROM %I c JOIN districts d ON d.id = c.district_id
        WHERE c.district_code IS DISTINCT FROM d.code', t) INTO drift;
    IF drift > 0 THEN
      RAISE EXCEPTION E'[DISTRICT_ID_DRIFT] % row(s) in % have a district_id whose registry code does not match their district_code.\n  The backfill above matched on code, so drift means the table changed mid-transaction. Nothing was changed.',
        drift, t;
    END IF;
    RAISE NOTICE '[0004] %.district_id agrees with .district_code: no drift', t;
  END LOOP;
END
$do$;

-- ─────────────────────────────────────────────────────────────────────────────
-- Grants for the runtime role. Roles are cluster-level and are NOT in a pg_dump, so on a
-- restored copy the role may not exist yet; skipping with a notice is correct there, and
-- silently failing a drill would be worse.
-- ─────────────────────────────────────────────────────────────────────────────

DO $do$
BEGIN
  IF to_regrole('dharohar_app') IS NULL THEN
    RAISE NOTICE '[0004] role dharohar_app does not exist in this cluster - grants skipped (run scripts/roles.sql, then re-run this file)';
  ELSE
    EXECUTE 'GRANT SELECT, INSERT, UPDATE ON TABLE organization_districts TO dharohar_app';
    EXECUTE 'GRANT SELECT, INSERT, UPDATE ON TABLE organization_units     TO dharohar_app';
    EXECUTE 'REVOKE DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE organization_districts FROM dharohar_app';
    EXECUTE 'REVOKE DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE organization_units     FROM dharohar_app';
    RAISE NOTICE '[0004] organization tables granted to dharohar_app (no DELETE, no TRUNCATE, no DDL)';
  END IF;
END
$do$;

-- ─────────────────────────────────────────────────────────────────────────────
-- Mapping report. The numbers in docs/DISTRICT-TENANCY-MODEL.md §5 should match this
-- output; a report that is only prose is a claim.
-- ─────────────────────────────────────────────────────────────────────────────

DO $do$
DECLARE
  r RECORD;
BEGIN
  RAISE NOTICE '[0004] ===== mapping report =====';
  FOR r IN SELECT kind, count(*) AS n FROM districts GROUP BY kind ORDER BY kind LOOP
    RAISE NOTICE '[0004] registry  kind=% rows=%', r.kind, r.n;
  END LOOP;
  RAISE NOTICE '[0004] associations active=% total=%',
    (SELECT count(*) FROM organization_districts WHERE revoked_at IS NULL),
    (SELECT count(*) FROM organization_districts);
  FOR r IN
    SELECT 'parcels' AS t, count(*) AS total, count(district_id) AS with_id FROM parcels
    UNION ALL SELECT 'land_documents', count(*), count(district_id) FROM land_documents
    UNION ALL SELECT 'users', count(*), count(district_id) FROM users
    UNION ALL SELECT 'user_jurisdictions', count(*), count(district_id) FROM user_jurisdictions
    ORDER BY t
  LOOP
    RAISE NOTICE '[0004] %: rows=% district_id_set=% null=%', r.t, r.total, r.with_id, r.total - r.with_id;
  END LOOP;
  RAISE NOTICE '[0004] organizations=%', (SELECT count(*) FROM organizations);
  RAISE NOTICE '[0004] ===== end report =====';
END
$do$;


